//! The basis of a refusal, which `basis()` answers from the `Basis:` line of the variant's doc
//! comment (`error/basis.rs`, generated by `scripts/refusal-surface/refusal_surface.py`).

use crate::RefusalBasis::{Device, MetalDocumented, MetalMeasured, Ours};
use crate::{Error, Gap, Limit, LinearPlanePassKind, Refusal};
use metal2vulkan::error::Error as Translator;

/// A variant of each basis `Refusal`, `Limit` and `Gap` declare answers it.
#[test]
fn each_refusal_enum_answers_its_declared_basis() {
    assert_eq!(Refusal::EmptyBuffer.basis(), MetalMeasured);
    assert_eq!(Refusal::Committed.basis(), MetalDocumented);
    assert_eq!(Refusal::ManagedCopyMissing.basis(), Ours);
    let kind = LinearPlanePassKind::DepthStencil;
    assert_eq!(Limit::DeviceSamplers { max: 16 }.basis(), Device);
    assert_eq!(Limit::BlockIds.basis(), Ours);
    assert_eq!(Gap::LinearPlanePass { kind }.basis(), Device);
    assert_eq!(Gap::CubicSampler.basis(), Ours);
    assert_eq!(Limit::LodClampVariants { max: 4000 }.basis(), Ours);
    assert_eq!(Limit::LevelElements { max: 4096 }.basis(), Ours);
}

/// A refusal enum's variant answers its own; a device that lacks the floor's mechanism `Device`;
/// a cancelled translation, a failed call and the consumer's own state none.
#[test]
fn an_error_answers_the_basis_of_what_it_carries() {
    let cases = [
        (Error::Refused(Refusal::Committed), Some(MetalDocumented)),
        (Error::Limit(Limit::BlockIds), Some(Ours)),
        (Error::Unsupported(Gap::CubicSampler), Some(Ours)),
        (Error::NoDirectDriverLoading, Some(Device)),
        (Error::translation(Translator::Cancelled), None),
        (Error::out_of_device_memory(), None),
        (Error::Quiesced, None),
    ];
    for (error, basis) in cases {
        assert_eq!(error.basis(), basis, "{error}");
    }
}

/// A translator's refusal answers the basis of what it needs, whatever its feature; its cap, its
/// deadline and its defect are ours; malformed input refuses no valid program.
#[test]
fn a_translation_error_answers_the_basis_of_what_it_needs() {
    use metal2vulkan::device::VkFeature;
    use metal2vulkan::error::{Capability, Feature, Limit, Needs, Unsupported};
    let refusal = |needs| {
        let mut refusal = Unsupported::not_implemented(Feature::Recursion);
        refusal.needs = needs;
        Error::translation(Translator::Unsupported(refusal))
    };
    let depth_clamp = vec![vec![Capability::Feature(VkFeature::DepthClamp)]];
    let cases = [
        (refusal(Needs::AnyOf(depth_clamp)), Some(Device)),
        (refusal(Needs::NotRepresentable), Some(Device)),
        (refusal(Needs::NotImplemented), Some(Ours)),
        (
            Error::translation(Translator::LimitExceeded(Limit::SpirvWords)),
            Some(Ours),
        ),
    ];
    for (error, basis) in cases {
        assert_eq!(error.basis(), basis, "{error}");
    }
    let Err(malformed) = metal2vulkan::library::Library::parse(b"not a library") else {
        panic!("bytes that are no library parsed");
    };
    assert!(
        matches!(malformed, Translator::InvalidInput(_)),
        "{malformed}"
    );
    assert_eq!(Error::translation(malformed).basis(), None);
}
